/**
 * emit.ts — render `src/generated/protocol.ts` from {@link schema.ts}.
 *
 * Follows the generator package's contract: pure function, deterministic
 * output, `@generated` banner on line 2 (scoreboard excludes it from the
 * hand-written LOC denominator), committed output guarded by `drift.test.ts`.
 */

import { ENUMS, MESSAGES, STRUCTS, type FieldDef } from "./schema.js";

const BANNER = `/**
 * @generated by @browser-engine/ipc — DO NOT EDIT BY HAND.
 *
 * Binary wire codec for the browser-process ↔ web-content protocol
 * (RFC 0004). Frame layout: [u32 totalLen][u64 requestId][u16 tag][payload].
 *
 * Regenerate with \`npm run generate --workspace @browser-engine/ipc\`.
 */`;

function lowerCamel(name: string): string {
  return name.charAt(0).toLowerCase() + name.slice(1);
}

/** The TypeScript type a field type maps to. */
function tsType(type: string): string {
  if (type.endsWith("?")) return `${tsType(type.slice(0, -1))} | null`;
  if (type.endsWith("[]")) return `readonly ${tsType(type.slice(0, -2))}[]`;
  if (type.startsWith("struct:")) return type.slice(7);
  if (type.startsWith("enum:")) return type.slice(5);
  switch (type) {
    case "u8":
    case "u16":
    case "u32":
    case "i32":
    case "f64":
      return "number";
    case "bool":
      return "boolean";
    case "string":
      return "string";
    case "bytes":
      return "Uint8Array";
    default:
      throw new Error(`unknown field type ${type}`);
  }
}

/**
 * The decode EXPRESSION for a field type — a single TS expression consuming
 * bytes from `r`. Compound shapes fall back to an IIFE so every field decodes
 * as one expression.
 */
function decodeExpr(type: string): string {
  if (type.endsWith("?")) {
    return `(r.u8() === 1 ? ${decodeExpr(type.slice(0, -1))} : null)`;
  }
  if (type.endsWith("[]")) {
    const inner = decodeExpr(type.slice(0, -2));
    return `(() => { const n = r.u32(); const a: ${tsType(type.slice(0, -2))}[] = []; for (let i = 0; i < n; i += 1) a.push(${inner}); return a; })()`;
  }
  if (type.startsWith("struct:")) return `read${type.slice(7)}(r)`;
  if (type.startsWith("enum:")) return `read${type.slice(5)}(r)`;
  switch (type) {
    case "u8":
    case "u16":
    case "u32":
    case "i32":
    case "f64":
      return `r.${type}()`;
    case "bool":
      return "r.bool()";
    case "string":
      return "r.str()";
    case "bytes":
      return "r.bytes()";
    default:
      throw new Error(`unknown field type ${type}`);
  }
}

/** Emit the `write` statement(s) for one field's value at expression `src`. */
function emitWriteField(field: FieldDef, src: string): string {
  const t = field.type;
  if (t.endsWith("?")) {
    const inner = emitWriteField({ ...field, type: t.slice(0, -1) }, src);
    const indented = inner
      .split("\n")
      .map((l) => `      ${l.trimStart()}`)
      .join("\n");
    return `    if (${src} === null || ${src} === undefined) {\n      w.u8(0);\n    } else {\n      w.u8(1);\n${indented}\n    }`;
  }
  if (t.endsWith("[]")) {
    const inner = emitWriteField({ ...field, type: t.slice(0, -2) }, "item");
    const indented = inner
      .split("\n")
      .map((l) => `      ${l.trimStart()}`)
      .join("\n");
    return `    w.u32(${src}.length);\n    for (const item of ${src}) {\n${indented}\n    }`;
  }
  if (t.startsWith("struct:")) return `    write${t.slice(7)}(w, ${src});`;
  if (t.startsWith("enum:")) return `    write${t.slice(5)}(w, ${src});`;
  switch (t) {
    case "u8":
    case "u16":
    case "u32":
    case "i32":
    case "f64":
      return `    w.${t}(${src});`;
    case "bool":
      return `    w.bool(${src});`;
    case "string":
      return `    w.str(${src});`;
    case "bytes":
      return `    w.bytes(${src});`;
    default:
      throw new Error(`unknown field type ${t}`);
  }
}

function emitRecordCodec(name: string, fields: readonly FieldDef[]): string {
  const writes = fields.map((f) => emitWriteField(f, `v.${f.name}`)).join("\n");
  const decls = fields.map((f) => `    const ${f.name} = ${decodeExpr(f.type)};`).join("\n");
  const values = fields.map((f) => `      ${f.name},`).join("\n");
  return `export interface ${name} {
${fields.map((f) => `  readonly ${f.name}: ${tsType(f.type)};`).join("\n")}
}

export function write${name}(w: Writer, v: ${name}): void {
${fields.length === 0 ? "    void v;\n" : `${writes}\n`}}

export function read${name}(r: Reader): ${name} {
${decls}
  return {
${values}
  };
}`;
}

/** Message interface = `kind` discriminant + the row's fields. */
function emitMessage(name: string, dir: "req" | "rep", fields: readonly FieldDef[]): string {
  const iface = dir === "req" ? `${name}Request` : name;
  const fieldLines =
    fields.length === 0
      ? ""
      : "\n" + fields.map((f) => `  readonly ${f.name}: ${tsType(f.type)};`).join("\n");
  const writes =
    fields.length === 0
      ? "    void w;\n    void v;\n"
      : fields.map((f) => emitWriteField(f, `v.${f.name}`)).join("\n") + "\n";
  const decls = fields.map((f) => `    const ${f.name} = ${decodeExpr(f.type)};`).join("\n");
  const values =
    fields.length === 0
      ? `      kind: "${lowerCamel(name)}",`
      : `      kind: "${lowerCamel(name)}",\n${fields.map((f) => `      ${f.name},`).join("\n")}`;
  const readHead = decls === "" ? "    void r;\n" : `${decls}\n`;
  return `export interface ${iface} {
  readonly kind: "${lowerCamel(name)}";${fieldLines}
}

export function write${name}(w: Writer, v: ${iface}): void {
${writes}}

export function read${name}(r: Reader): ${iface} {
${readHead}  return {
${values}
  };
}`;
}

const WRITER_READER = `/**
 * Wire cursor: a growable little-endian buffer. Strings are utf8 with a u32
 * byte length; byte blobs are u32 length + raw bytes.
 */
export class Writer {
  #buf: ArrayBuffer;
  #view: DataView;
  #u8: Uint8Array;
  #len = 0;

  constructor(capacity = 256) {
    this.#buf = new ArrayBuffer(capacity);
    this.#view = new DataView(this.#buf);
    this.#u8 = new Uint8Array(this.#buf);
  }

  get length(): number {
    return this.#len;
  }

  #need(n: number): void {
    if (this.#len + n <= this.#buf.byteLength) return;
    let cap = this.#buf.byteLength * 2;
    while (cap < this.#len + n) cap *= 2;
    const next = new ArrayBuffer(cap);
    new Uint8Array(next).set(this.#u8.subarray(0, this.#len));
    this.#buf = next;
    this.#view = new DataView(next);
    this.#u8 = new Uint8Array(next);
  }

  u8(v: number): void {
    this.#need(1);
    this.#view.setUint8(this.#len, v);
    this.#len += 1;
  }

  u16(v: number): void {
    this.#need(2);
    this.#view.setUint16(this.#len, v, true);
    this.#len += 2;
  }

  u32(v: number): void {
    this.#need(4);
    this.#view.setUint32(this.#len, v, true);
    this.#len += 4;
  }

  i32(v: number): void {
    this.#need(4);
    this.#view.setInt32(this.#len, v, true);
    this.#len += 4;
  }

  f64(v: number): void {
    this.#need(8);
    this.#view.setFloat64(this.#len, v, true);
    this.#len += 8;
  }

  u64(v: number): void {
    this.#need(8);
    this.#view.setBigUint64(this.#len, BigInt(v), true);
    this.#len += 8;
  }

  bool(v: boolean): void {
    this.u8(v ? 1 : 0);
  }

  str(v: string): void {
    const bytes = new TextEncoder().encode(v);
    this.u32(bytes.length);
    this.#need(bytes.length);
    this.#u8.set(bytes, this.#len);
    this.#len += bytes.length;
  }

  bytes(v: Uint8Array): void {
    this.u32(v.byteLength);
    this.#need(v.byteLength);
    this.#u8.set(v, this.#len);
    this.#len += v.byteLength;
  }

  /** Patch bytes [at, at+4) with a u32 — used to back-patch the frame length. */
  patchU32(at: number, v: number): void {
    this.#view.setUint32(at, v, true);
  }

  /** Detach the written prefix as its own transferable buffer. */
  finish(): ArrayBuffer {
    return this.#buf.slice(0, this.#len);
  }
}

export class Reader {
  #view: DataView;
  #u8: Uint8Array;
  #pos = 0;
  #size: number;

  constructor(buf: ArrayBuffer | Uint8Array) {
    if (buf instanceof Uint8Array) {
      this.#view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
      this.#u8 = buf;
      this.#size = buf.byteLength;
    } else {
      this.#view = new DataView(buf);
      this.#u8 = new Uint8Array(buf);
      this.#size = buf.byteLength;
    }
  }

  /** Total byte size of the frame under the cursor. */
  get size(): number {
    return this.#size;
  }

  get remaining(): number {
    return this.#size - this.#pos;
  }

  #take(n: number): number {
    if (this.#pos + n > this.#size) {
      throw new Error("ipc: truncated frame");
    }
    const at = this.#pos;
    this.#pos += n;
    return at;
  }

  u8(): number {
    return this.#view.getUint8(this.#take(1));
  }

  u16(): number {
    return this.#view.getUint16(this.#take(2), true);
  }

  u32(): number {
    return this.#view.getUint32(this.#take(4), true);
  }

  i32(): number {
    return this.#view.getInt32(this.#take(4), true);
  }

  f64(): number {
    return this.#view.getFloat64(this.#take(8), true);
  }

  u64(): number {
    const v = this.#view.getBigUint64(this.#take(8), true);
    if (v > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error("ipc: requestId overflow");
    return Number(v);
  }

  bool(): boolean {
    return this.u8() !== 0;
  }

  str(): string {
    const len = this.u32();
    const at = this.#take(len);
    return new TextDecoder().decode(this.#u8.subarray(at, at + len));
  }

  bytes(): Uint8Array {
    const len = this.u32();
    const at = this.#take(len);
    return this.#u8.slice(at, at + len);
  }
}`;

/** Render the full protocol.ts source. */
export function emitProtocol(): string {
  const parts: string[] = [BANNER, WRITER_READER];

  for (const [name, values] of Object.entries(ENUMS)) {
    const table = `${name.toUpperCase()}_VALUES`;
    parts.push(`export const ${table} = [${values.map((v) => `"${v}"`).join(", ")}] as const;
export type ${name} = (typeof ${table})[number];

export function write${name}(w: Writer, v: ${name}): void {
    w.u8(${table}.indexOf(v));
}

export function read${name}(r: Reader): ${name} {
    const i = r.u8();
    const v = ${table}[i];
    if (v === undefined) throw new Error(\`ipc: bad ${name} tag \${i}\`);
    return v;
}`);
  }

  for (const struct of STRUCTS) {
    parts.push(emitRecordCodec(struct.name, struct.fields));
  }

  const tagOf = new Map<string, number>();
  let tag = 1;
  for (const m of MESSAGES) {
    tagOf.set(m.name, m.name === "Error" ? 0 : tag++);
  }

  parts.push(`export const MessageTag = {
${MESSAGES.map((m) => `  ${lowerCamel(m.name)}: ${tagOf.get(m.name)},`).join("\n")}
} as const;`);

  for (const m of MESSAGES) {
    parts.push(emitMessage(m.name, m.dir, m.fields));
  }

  const requests = MESSAGES.filter((m) => m.dir === "req");
  const replies = MESSAGES.filter((m) => m.dir === "rep");
  parts.push(`export type AppRequest = ${requests.map((m) => `${m.name}Request`).join(" | ")};
export type AppReply = ${replies.map((m) => m.name).join(" | ")};`);

  parts.push(`/** Encode [u32 len][u64 requestId][u16 tag][payload]. */
export function encodeRequest(requestId: number, msg: AppRequest): ArrayBuffer {
  const w = new Writer();
  w.u32(0);
  w.u64(requestId);
  const tag: number = MessageTag[msg.kind as keyof typeof MessageTag];
  w.u16(tag);
  switch (msg.kind) {
${requests.map((m) => `    case "${lowerCamel(m.name)}": write${m.name}(w, msg); break;`).join("\n")}
  }
  w.patchU32(0, w.length);
  return w.finish();
}

export function decodeRequest(buf: ArrayBuffer | Uint8Array): { requestId: number; msg: AppRequest } {
  const r = new Reader(buf);
  const totalLen = r.u32();
  const requestId = r.u64();
  const tag = r.u16();
  if (totalLen !== r.size) throw new Error(\`ipc: frame length \${totalLen} != buffer \${r.size}\`);
  let msg: AppRequest;
  switch (tag) {
${requests.map((m) => `    case ${tagOf.get(m.name)}: msg = read${m.name}(r); break;`).join("\n")}
    default: throw new Error(\`ipc: unknown request tag \${tag}\`);
  }
  if (r.remaining !== 0) throw new Error(\`ipc: trailing bytes in request tag \${tag}\`);
  return { requestId, msg };
}

export function encodeReply(requestId: number, msg: AppReply): ArrayBuffer {
  const w = new Writer();
  w.u32(0);
  w.u64(requestId);
  const tag: number = MessageTag[msg.kind as keyof typeof MessageTag];
  w.u16(tag);
  switch (msg.kind) {
${replies.map((m) => `    case "${lowerCamel(m.name)}": write${m.name}(w, msg); break;`).join("\n")}
  }
  w.patchU32(0, w.length);
  return w.finish();
}

export function decodeReply(buf: ArrayBuffer | Uint8Array): { requestId: number; msg: AppReply } {
  const r = new Reader(buf);
  const totalLen = r.u32();
  const requestId = r.u64();
  const tag = r.u16();
  if (totalLen !== r.size) throw new Error(\`ipc: frame length \${totalLen} != buffer \${r.size}\`);
  let msg: AppReply;
  switch (tag) {
${replies.map((m) => `    case ${tagOf.get(m.name)}: msg = read${m.name}(r); break;`).join("\n")}
    default: throw new Error(\`ipc: unknown reply tag \${tag}\`);
  }
  if (r.remaining !== 0) throw new Error(\`ipc: trailing bytes in reply tag \${tag}\`);
  return { requestId, msg };
}`);

  return parts.join("\n\n") + "\n";
}
